//! Generated protocol bindings for `proto/preloop/sandbox/v1/sandbox.proto`.
//!
//! Regenerate with `scripts/gen-sandbox-proto.sh` — never edit the two
//! `include!`d files by hand. `preloop.sandbox.v1.rs` holds the buffa message
//! types (owned structs plus their borrowed views); `preloop.sandbox.v1.connect.rs`
//! holds the `Sandboxes` and `Providers` service traits, typed clients and
//! method specs generated by connect-rust.
//!
//! The workspace denies nothing here, but generated code legitimately trips
//! style lints and carries no doc comments on every item, so every lint the
//! two files can produce is allowed at this module boundary and nowhere else.

#![allow(
    missing_docs,
    dead_code,
    unused_imports,
    unused_qualifications,
    unused_variables,
    unused_mut,
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    clippy::all,
    clippy::pedantic,
    clippy::nursery,
    clippy::restriction,
    clippy::cargo
)]

pub mod preloop {
    pub mod sandbox {
        pub mod v1 {
            include!("preloop.sandbox.v1.rs");
            include!("preloop.sandbox.v1.connect.rs");
        }
    }
}
